WITH RankedPosts AS (SELECT p.Id, p.Title, p.CreationDate, p.Score, p.ViewCount, U.Reputation AS OwnerReputation, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p JOIN Users AS U ON p.OwnerUserId = U.Id WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR AND p.ViewCount > 100), UserBadges AS (SELECT b.UserId, GROUP_CONCAT(b.Name, ', ') AS BadgeNames, COUNT(*) AS BadgeCount FROM Badges AS b GROUP BY b.UserId) SELECT RP.Id AS PostId, RP.Title, RP.CreationDate, RP.Score, RP.ViewCount, RB.BadgeNames, RB.BadgeCount FROM RankedPosts AS RP LEFT JOIN UserBadges AS RB ON RP.Id = RB.UserId WHERE RP.PostRank = 1 AND (RB.BadgeCount IS NULL OR RB.BadgeCount > 5) ORDER BY RP.Score DESC NULLS FIRST LIMIT 10